package com.mediconnect.observability; import java.util.*; import io.github.resilience4j.circuitbreaker.CircuitBreaker; import org.springframework.boot.actuate.endpoint.annotation.*; import org.springframework.stereotype.Component; @Component @Endpoint(id="mediconnect") public class MediConnectEndpoint { private final CircuitBreaker openFdaCircuitBreaker; public MediConnectEndpoint(CircuitBreaker openFdaCircuitBreaker){this.openFdaCircuitBreaker=openFdaCircuitBreaker;} @ReadOperation public Map<String,Object> status(){Map<String,Object> result=new LinkedHashMap<>();result.put("application","MediConnect Enterprise Pro");result.put("openFdaCircuitBreaker",openFdaCircuitBreaker.getState().name());result.put("requestHandledByVirtualThread",Thread.currentThread().isVirtual());return result;} }
